use vstd::prelude::*;

verus! {
    fn min_inspectors(n: i8, d: i8) -> (result: i8)
        requires
            n >= 1 && n <= 20,
            d >= 1 && d <= 20,
        ensures
            result >= 1 && result <= n,
            result == (n + (2 * d) as i8) / ((2 * d + 1) as i8),
    {
        let coverage_length: i8 = 2 * d + 1;
        let mut inspectors: i8 = 0;
        let mut items_covered: i8 = 0;

        while items_covered < n
            invariant
                items_covered <= n,
                inspectors >= 0,
                items_covered == inspectors * coverage_length,
            decreases n - items_covered,
        {
            inspectors = inspectors + 1;
            items_covered = inspectors * coverage_length;
        }

        result = inspectors;
    }
}
